\version "2.27.2"
% automatically converted by musicxml2ly from 46j-EmptyMeasure.xml
\pointAndClickOff

\header {
  texidoc = "Measure two is empty; it only contains a time signature but not
    anything else. Some applications use this approach to insert time signatures
    for purely visual reasons, for example, displaying a final time signature at
    the end of a line, followed by a forced line break.

    While doing so is valid MusicXML, having measures with a zero length is
    semantically questionable. In particular, if the displayed bar number is
    derived from ‘<measure number=\"...\">’ (as it usually is), such empty
    measures make the bar numbers being off. Additionally, it is not portable,
    since other applications ‘rectify’ it by displaying this empty measure,
    giving it a default length."
}
\layout {
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative d' {
  \clef "treble" \numericTimeSignature \time 4/4 d4 e4 f4 g4 | % 1
  \time 3/4 s2. \break | % 2
  \time 3/4 a4 a4 a4 }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
